--- v8-probe.mjs
+++ v8-probe-graphs.mjs
@@ -51,12 +51,39 @@
   assert.equal(process.version, 'v24.18.0', 'requires the pinned Node version');
   assert.ok(!process.env.NODE_OPTIONS, 'NODE_OPTIONS must be empty for an explicit runtime configuration');
   assert.ok(['clean', 'trace', 'cpu', 'allocation'].includes(mode), 'invalid mode');
-  const traces = new Set(['--trace-opt', '--trace-deopt', '--trace-gc', '--trace-gc-nvp', '--trace-turbo-inlining']);
-  for (const flag of process.execArgv) assert.ok(
-    /^--(?:stack-size|max-old-space-size)=\d+$/.test(flag) || (mode === 'trace' && traces.has(flag)),
-    `unsupported or mixed instrumentation flag: ${flag}`);
-  if (mode === 'trace') assert.ok(process.execArgv.includes('--trace-opt')
-    && process.execArgv.includes('--trace-deopt'), 'trace mode requires --trace-opt --trace-deopt');
+  const traces = new Set(['--trace-opt', '--trace-deopt', '--trace-gc', '--trace-gc-nvp', '--trace-turbo-inlining',
+    '--trace-turbo', '--trace-turbo-graph', '--print-opt-code']);
+  const diagnosticOptions = new Map();
+  for (const flag of process.execArgv) {
+    const option = /^--(trace-turbo-filter|trace-turbo-path|trace-turbo-cfg-file|print-opt-code-filter)=(.+)$/.exec(flag);
+    assert.ok(/^--(?:stack-size|max-old-space-size)=\d+$/.test(flag)
+      || (mode === 'trace' && (traces.has(flag) || option)),
+      `unsupported or mixed instrumentation flag: ${flag}`);
+    if (option) {
+      const [, key, value] = option;
+      assert.ok(!diagnosticOptions.has(key), `duplicate diagnostic option: ${key}`);
+      if (key.endsWith('-filter')) assert.ok(value.length <= 160 && /^[A-Za-z_$][A-Za-z0-9_$.]*$/.test(value),
+        `require one bounded literal function name: ${key}`);
+      else assert.ok(path.isAbsolute(value) && path.normalize(value) === value
+        && !/[\0\r\n*?]/.test(value), `require an absolute normalized diagnostic path: ${key}`);
+      diagnosticOptions.set(key, value);
+    }
+  }
+  if (mode === 'trace') {
+    assert.ok(process.execArgv.includes('--trace-opt') && process.execArgv.includes('--trace-deopt'),
+      'trace mode requires --trace-opt --trace-deopt');
+    if (process.execArgv.includes('--trace-turbo') || process.execArgv.includes('--trace-turbo-graph')) {
+      for (const key of ['trace-turbo-filter', 'trace-turbo-path', 'trace-turbo-cfg-file'])
+        assert.ok(diagnosticOptions.has(key), `graph diagnostics require ${key}`);
+      const dumps = diagnosticOptions.get('trace-turbo-path'), cfg = diagnosticOptions.get('trace-turbo-cfg-file');
+      assert.ok(fs.statSync(dumps).isDirectory(), 'graph dump directory must exist');
+      assert.ok(path.dirname(cfg) === dumps, 'CFG output must be inside graph dump directory');
+      // The runner reserves a fresh directory before Node starts: V8 can open
+      // its CFG output before this JavaScript configuration check executes.
+    }
+    if (process.execArgv.includes('--print-opt-code')) assert.ok(diagnosticOptions.has('print-opt-code-filter'),
+      'optimized code diagnostics require an exact function filter');
+  }
   assert.ok(typeof exportName === 'string' && exportName.length > 0 && Array.isArray(args));
   assert.ok(typeof expected === 'number' && Number.isFinite(expected), 'expected must be a finite number');
   numericJson(args);
